1	#!/usr/bin/env node
2	// Offline generator for cli/src/providers.generated.ts from a models.dev api.json (MIT, github.com/sst/models.dev).
3	// It never touches the network: fetch api.json yourself first (see docs/CLOUD_PROVIDERS.md).
4	//   node scripts/gen_models_snapshot.mjs <api.json> --date YYYY-MM-DD [--commit <sha>] [--tools-from <models.dev clone>] [--out <file>]
5	// api.json carries no tool_choice data; --tools-from reads `capabilities.tools.choice` from the clone's TOML (data only,
6	// read as text; nothing in the clone is executed). Pruning rule: only chat models (type absent or "chat") that support
7	// tool calls (the harness is agentic), no deprecated/alpha status, no non-HTTP (ws://, wss://) endpoint. Repeated
8	// effort and tool-choice arrays are emitted once as tables (E, T) and referenced by index.
9	import fs from "node:fs";
10	import path from "node:path";
11	import { fileURLToPath } from "node:url";
12	
13	const OPENAI_CHAT_NPM = new Set([
14	  "@ai-sdk/openai-compatible", "@ai-sdk/groq", "@ai-sdk/mistral", "@ai-sdk/xai", "@ai-sdk/cerebras",
15	  "@ai-sdk/togetherai", "@ai-sdk/perplexity", "@ai-sdk/deepinfra", "@openrouter/ai-sdk-provider",
16	]);
17	
18	export function protocolClass(npm) {
19	  if (OPENAI_CHAT_NPM.has(npm)) return "openai-chat";
20	  if (npm === "@ai-sdk/openai") return "openai-responses";
21	  if (npm === "@ai-sdk/anthropic") return "anthropic-messages";
22	  return `native:${npm}`;
23	}
24	
25	const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0);
26	const num = (v) => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? v : undefined);
27	
28	export function keepModel(m) {
29	  if (m.type !== undefined && m.type !== "chat") return false;
30	  if (m.tool_call !== true) return false;
31	  if (m.status === "deprecated" || m.status === "alpha") return false;
32	  if (typeof m.provider?.api === "string" && !/^https?:/.test(m.provider.api)) return false;
33	  return true;
34	}
35	
36	export function toolChoiceFromToml(text) {
37	  const line = text.split("\n").find((l) => /^tools\s*=\s*\{/.test(l));
38	  const match = line && /choice\s*=\s*\[([^\]]*)\]/.exec(line);
39	  if (!match) return undefined;
40	  const modes = [...match[1].matchAll(/"([^"]+)"/g)].map((x) => x[1]);
41	  return modes.length ? modes : undefined;
42	}
43	
44	export function readToolChoice(cloneDir, providerId, modelId) {
45	  const read = (p) => (fs.existsSync(p) ? fs.readFileSync(p, "utf8") : undefined);
46	  const own = read(path.join(cloneDir, "providers", providerId, "models", `${modelId}.toml`));
47	  if (own === undefined) return undefined;
48	  const direct = toolChoiceFromToml(own);
49	  if (direct) return direct;
50	  const base = /^base_model\s*=\s*"([^"]+)"/m.exec(own)?.[1];
51	  if (!base || base.includes("..")) return undefined;
52	  const baseText = read(path.join(cloneDir, "models", `${base}.toml`));
53	  return baseText === undefined ? undefined : toolChoiceFromToml(baseText);
54	}
55	
56	export function buildModel(m, toolChoice) {
57	  const out = { id: m.id, context: num(m.limit?.context) ?? 0, output: num(m.limit?.output) ?? 0 };
58	  const input = num(m.limit?.input);
59	  if (input !== undefined) out.input = input;
60	  out.toolCall = m.tool_call === true;
61	  if (toolChoice) out.toolChoice = toolChoice;
62	  out.reasoning = m.reasoning === true;
63	  const effort = (m.reasoning_options ?? []).find((o) => o.type === "effort" && Array.isArray(o.values))?.values;
64	  if (effort?.length) out.effort = [...effort];
65	  const pin = num(m.cost?.input);
66	  const pout = num(m.cost?.output);
67	  if (pin !== undefined && pout !== undefined) out.price = { input: pin, output: pout };
68	  return out;
69	}
70	
71	export function buildSnapshot(api, { date, commit, toolsFrom } = {}) {
72	  const providers = Object.keys(api).sort(cmp).map((key) => {
73	    const p = api[key];
74	    const entry = { id: p.id ?? key, name: p.name, env: [...(p.env ?? [])], protocol: protocolClass(p.npm) };
75	    if (typeof p.api === "string" && p.api) entry.baseUrl = p.api;
76	    entry.models = Object.values(p.models ?? {})
77	      .filter(keepModel)
78	      .sort((a, b) => cmp(a.id, b.id))
79	      .map((m) => buildModel(m, toolsFrom ? readToolChoice(toolsFrom, entry.id, m.id) : undefined));
80	    return entry;
81	  });
82	  return { date, ...(commit ? { commit } : {}), license: "MIT", source: "https://models.dev/api.json", providers };
83	}
84	
85	export function validateSnapshot(s) {
86	  const errors = [];
87	  const bad = (m) => errors.push(m);
88	  if (!/^\d{4}-\d{2}-\d{2}$/.test(s?.date ?? "")) bad("date must be YYYY-MM-DD");
89	  if (!Array.isArray(s?.providers) || s.providers.length === 0) return [...errors, "providers must be a non-empty array"];
90	  const seen = new Set();
91	  for (const p of s.providers) {
92	    const where = `provider ${p?.id}`;
93	    if (typeof p.id !== "string" || !p.id) bad(`${where}: id`);
94	    if (seen.has(p.id)) bad(`${where}: duplicate`);
95	    seen.add(p.id);
96	    if (typeof p.name !== "string" || !p.name) bad(`${where}: name`);
97	    if (typeof p.protocol !== "string" || !(/^(openai-chat|openai-responses|anthropic-messages)$/.test(p.protocol) || /^native:.+/.test(p.protocol))) bad(`${where}: protocol`);
98	    if (!Array.isArray(p.env) || p.env.some((e) => typeof e !== "string")) bad(`${where}: env`);
99	    if (p.baseUrl !== undefined && typeof p.baseUrl !== "string") bad(`${where}: baseUrl`);
100	    const ids = new Set();
101	    for (const m of p.models ?? []) {
102	      const mw = `${where} model ${m?.id}`;
103	      if (typeof m.id !== "string" || !m.id) bad(`${mw}: id`);
104	      if (ids.has(m.id)) bad(`${mw}: duplicate`);
105	      ids.add(m.id);
106	      for (const k of ["context", "output", "input"]) {
107	        if (m[k] !== undefined && !(Number.isFinite(m[k]) && m[k] >= 0)) bad(`${mw}: ${k}`);
108	      }
109	      if (typeof m.toolCall !== "boolean" || typeof m.reasoning !== "boolean") bad(`${mw}: toolCall/reasoning`);
110	      for (const k of ["toolChoice", "effort"]) {
111	        if (m[k] !== undefined && (!Array.isArray(m[k]) || m[k].some((x) => typeof x !== "string"))) bad(`${mw}: ${k}`);
112	      }
113	      if (m.price !== undefined && !(Number.isFinite(m.price.input) && Number.isFinite(m.price.output))) bad(`${mw}: price`);
114	    }
115	  }
116	  return errors;
117	}
118	
119	export function renderSnapshot(s) {
120	  const tables = { effort: new Map(), toolChoice: new Map() };
121	  for (const p of s.providers) for (const m of p.models) for (const k of Object.keys(tables)) if (m[k]) tables[k].set(JSON.stringify(m[k]), 0);
122	  for (const k of Object.keys(tables)) {
123	    const sorted = [...tables[k].keys()].sort(cmp);
124	    tables[k] = new Map(sorted.map((key, i) => [key, i]));
125	  }
126	  const model = (m) => {
127	    const parts = [`id:${JSON.stringify(m.id)}`, `context:${m.context}`, `output:${m.output}`];
128	    if (m.input !== undefined) parts.push(`input:${m.input}`);
129	    parts.push(`toolCall:${m.toolCall}`);
130	    if (m.toolChoice) parts.push(`toolChoice:T[${tables.toolChoice.get(JSON.stringify(m.toolChoice))}]`);
131	    parts.push(`reasoning:${m.reasoning}`);
132	    if (m.effort) parts.push(`effort:E[${tables.effort.get(JSON.stringify(m.effort))}]`);
133	    if (m.price) parts.push(`price:{input:${m.price.input},output:${m.price.output}}`);
134	    return `{${parts.join(",")}}`;
135	  };
136	  const rows = s.providers.map((p) => {
137	    const { models, ...head } = p;
138	    return `{...${JSON.stringify(head)},models:[\n${models.map(model).join(",\n")}]}`;
139	  });
140	  const table = (name, t) => `const ${name}: string[][] = [${[...t.keys()].join(",")}];`;
141	  const meta = { date: s.date, ...(s.commit ? { commit: s.commit } : {}), license: s.license, source: s.source };
142	  return `// GENERATED by scripts/gen_models_snapshot.mjs from models.dev (MIT licence, https://github.com/sst/models.dev).
143	// Snapshot date: ${s.date}${s.commit ? `; source commit: ${s.commit}` : ""}. Do not edit; regenerate offline (docs/CLOUD_PROVIDERS.md).
144	import type { ModelsSnapshot } from "./core/models_snapshot.js";
145	
146	${table("E", tables.effort)}
147	${table("T", tables.toolChoice)}
148	
149	export const MODELS_SNAPSHOT: ModelsSnapshot = {...${JSON.stringify(meta)},providers:[
150	${rows.join(",\n")}]};
151	`;
152	}
153	
154	function main(argv) {
155	  const opt = {};
156	  const files = [];
157	  for (let i = 0; i < argv.length; i++) {
158	    if (argv[i].startsWith("--")) opt[argv[i].slice(2)] = argv[++i];
159	    else files.push(argv[i]);
160	  }
161	  if (files.length !== 1 || !opt.date) {
162	    console.error("usage: gen_models_snapshot.mjs <api.json> --date YYYY-MM-DD [--commit sha] [--tools-from <clone>] [--out file]");
163	    return 2;
164	  }
165	  const snapshot = buildSnapshot(JSON.parse(fs.readFileSync(files[0], "utf8")), { date: opt.date, commit: opt.commit, toolsFrom: opt["tools-from"] });
166	  const errors = validateSnapshot(snapshot);
167	  if (errors.length) {
168	    console.error(`snapshot invalid:\n${errors.slice(0, 20).join("\n")}`);
169	    return 1;
170	  }
171	  const out = opt.out ?? path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../cli/src/providers.generated.ts");
172	  const text = renderSnapshot(snapshot);
173	  fs.writeFileSync(out, text);
174	  console.log(`${out}: ${Buffer.byteLength(text)} bytes, ${snapshot.providers.length} providers, ${snapshot.providers.reduce((n, p) => n + p.models.length, 0)} models`);
175	  return 0;
176	}
177	
178	if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) process.exitCode = main(process.argv.slice(2));
179

